parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "section_name": {
      "type": "string",
      "description": "Name of the analyzed section (e.g., 'Page Metadata & Identity' or 'Main Content Part 1')"
    },
    "relevance_score": {
      "type": "number",
      "description": "Score from 0-100 indicating SEO quality",
      "minimum": 0,
      "maximum": 100
    },
    "page_type_detected": {
      "type": "string",
      "description": "The type of page detected based on metadata (e.g., 'News Article', 'Category Hub', 'Landing Page', or 'N/A' if just a content chunk)"
    },
    "critical_issues": {
      "type": "array",
      "items": {
        "type": "string"
      },
      "description": "List of severe errors (e.g., 'Missing H1', 'Stuffed Keywords', 'Wall of Text')"
    },
    "optimization_recommendations": {
      "type": "array",
      "items": {
        "type": "string"
      },
      "description": "List of specific, actionable improvements"
    },
    "keyword_analysis": {
      "type": "string",
      "description": "A specific summary of how the target keyword is used (density, placement, natural flow)"
    }
  },
  "required": [
    "section_name",
    "relevance_score",
    "page_type_detected",
    "critical_issues",
    "optimization_recommendations",
    "keyword_analysis"
  ]
}

parameters.jsCode:
// Extract URL and target keyword from form input
const inputUrl = $input.item.json.url;
const targetKeyword = $input.item.json.target_keyword;

// Parse the root domain from the URL
let rootDomain = '';
try {
  const match = inputUrl.match(/^(https?:\/\/[^\/]+)/);
  rootDomain = match ? match[1] : inputUrl;
} catch (e) {
  rootDomain = inputUrl;
}

// Return parsed data
return [{
  json: {
    original_url: inputUrl,
    root_domain: rootDomain,
    target_keyword: targetKeyword
  }
}];

// 1. Get the Clean Data from the "HTML Extract" node
// Note: We use the incoming data directly.
const input = $input.first().json;

// 2. Get the Target Keyword from your Form
// (We add a fallback just in case the form is empty)
let targetKeyword = "General SEO";
try {
    targetKeyword = $('SEO Audit Form').first().json.target_keyword;
} catch (e) {
    // If form name is different, we proceed without crashing
}

// 3. Set Variables (Handling missing data gracefully)
const title = input.pageTitle || "No Title Found";
const h1 = input.h1 || "No H1 Tag Found";
const meta = input.metaDesc || "No Meta Description";
let bodyText = input.mainContent || "";

// Clean up extra whitespace/newlines to save AI tokens
bodyText = bodyText.replace(/\s+/g, ' ').trim();

const sections = [];

// --- SECTION 1: METADATA (The "Identity") ---
// We send this first so the AI knows if it's a News Article or a Category Page
sections.push({
    section_name: "Page Metadata & Identity",
    content: `Page Title: ${title}\nH1 Tag: ${h1}\nMeta Description: ${meta}`,
    target_keyword: targetKeyword,
    is_metadata: true
});

// --- SECTION 2: MAIN CONTENT (Chunked) ---
// We split the body into chunks of 3000 characters so the AI doesn't crash
const chunkSize = 3000;

if (bodyText.length < 50) {
    // Fallback: If body is empty (extraction failed), warn the AI
    sections.push({
        section_name: "Content Warning",
        content: "Main content text was too short or could not be extracted. Analyze based on Metadata only.",
        target_keyword: targetKeyword,
        is_metadata: false
    });
} else {
    for (let i = 0; i < bodyText.length; i += chunkSize) {
        sections.push({
            section_name: `Main Content Part ${Math.floor(i / chunkSize) + 1}`,
            content: bodyText.substring(i, i + chunkSize),
            target_keyword: targetKeyword,
            is_metadata: false
        });

        // SAFETY LIMIT: Stop after 4 chunks (12,000 chars) to save money/tokens
        // You can increase this number if you want to analyze longer pages
        if (i > 12000) break;
    }
}

// 4. Return the array in n8n format
return sections.map(section => ({ json: section }));
